const root = window.document.documentElement;
const body = window.document.body;

// Replicate the logic from main.ts to verify it.
function handleKeyboardShow(event) {
  const keyboardHeight = event?.detail?.keyboardHeight ?? event?.keyboardHeight;
  if (typeof keyboardHeight !== 'number') return;
  root.style.setProperty('--keyboard-offset', `${keyboardHeight}px`);
  body.classList.add('keyboard-open');
}
function handleKeyboardHide() {
  root.style.setProperty('--keyboard-offset', '0px');
  body.classList.remove('keyboard-open');
}

window.addEventListener('keyboardWillShow', handleKeyboardShow);
window.addEventListener('keyboardWillHide', handleKeyboardHide);

// Simulate keyboardWillShow
window.dispatchEvent(new window.Event('keyboardWillShow'));
console.log('After keyboardWillShow (no height):', root.style.getPropertyValue('--keyboard-offset'), body.className);

const showEvent = new window.Event('keyboardWillShow');
showEvent.keyboardHeight = 300;
window.dispatchEvent(showEvent);
console.log('After keyboardWillShow (300):', root.style.getPropertyValue('--keyboard-offset'), body.className);

const showEvent2 = new window.Event('keyboardDidShow');
