// Minimal DOM mock to verify the keyboard event logic.
class Style {
  constructor() { this._props = new Map(); }
  setProperty(k, v) { this._props.set(k, v); }
  getPropertyValue(k) { return this._props.get(k) || ''; }
}
class ClassList {
  constructor() { this.set = new Set(); }
  add(c) { this.set.add(c); }
  remove(c) { this.set.delete(c); }
  contains(c) { return this.set.has(c); }
  get length() { return this.set.size; }
  get value() { return [...this.set].join(' '); }
}
const root = { style: new Style() };
const body = { classList: new ClassList() };
const handlers = {};
const window = {
  addEventListener(name, fn) { handlers[name] = fn; },
  dispatchEvent(evt) { handlers[evt.type]?.(evt); },
};

// Copy the exact logic from src/main.ts
function handleKeyboardShow(event) {
  const keyboardHeight = event?.detail?.keyboardHeight ?? event?.keyboardHeight;
  if (typeof keyboardHeight !== 'number') return;
  root.style.setProperty('--keyboard-offset', `${keyboardHeight}px`);
  body.classList.add('keyboard-open');
}
function handleKeyboardHide() {
  root.style.setProperty('--keyboard-offset', '0px');
  body.classList.remove('keyboard-open');
}

window.addEventListener('keyboardWillShow', handleKeyboardShow);
window.addEventListener('keyboardWillHide', handleKeyboardHide);

function evt(type, props = {}) {
  const e = { type, ...props };
  return e;
}

// Test 1: keyboardWillShow with keyboardHeight=300 directly on the event
window.dispatchEvent(evt('keyboardWillShow', { keyboardHeight: 300 }));
console.assert(root.style.getPropertyValue('--keyboard-offset') === '300px', 'should be 300px');
console.assert(body.classList.contains('keyboard-open'), 'should have keyboard-open class');
console.log('Test 1 passed:', root.style.getPropertyValue('--keyboard-offset'), '/ class:', body.classList.value);

// Test 2: keyboardDidShow with a different height
window.dispatchEvent(evt('keyboardDidShow', { keyboardHeight: 450 }));
console.assert(root.style.getPropertyValue('--keyboard-offset') === '450px', 'should be 450px');
console.log('Test 2 passed:', root.style.getPropertyValue('--keyboard-offset'));

// Test 3: keyboardWillHide resets to 0px and removes class
window.dispatchEvent(evt('keyboardWillHide'));
console.assert(root.style.getPropertyValue('--keyboard-offset') === '0px', 'should be 0px');
console.assert(!body.classList.contains('keyboard-open'), 'should NOT have keyboard-open class');
console.log('Test 3 passed:', root.style.getPropertyValue('--keyboard-offset'), '/ class:', body.classList.value);

// Test 4: keyboardWillShow without height is a no-op
root.style.setProperty('--keyboard-offset', '99px');
window.dispatchEvent(evt('keyboardWillShow'));
console.assert(root.style.getPropertyValue('--keyboard-offset') === '99px', 'should remain 99px');
console.log('Test 4 passed: no-op when height missing:', root.style.getPropertyValue('--keyboard-offset'));

console.log('\nAll keyboard event handler tests passed.');
EOF
